"use client";import Link from "next/link";import { useEffect,useState } from "react";import { Festival } from "@/lib/types";import { seedFestivals } from "@/lib/festivals";import { categoryLabel } from "@/lib/types";
export function EventDetail({id,slug}:{id:string;slug:string}){const [f,setF]=useState<Festival|undefined>(seedFestivals.find(x=>x.id===id&&x.slug===slug));useEffect(()=>{if(!f){try{setF((JSON.parse(localStorage.getItem("matsuri-submissions")||"[]") as Festival[]).find(x=>x.id===id&&x.slug===slug))}catch{}}},[f,id,slug]);if(!f)return <main className="wrap section empty"><h1>Festival not found</h1><p>This festival may have ended or is no longer available.</p><Link href="/" className="button">Back to Festivals</Link></main>;const fields:[[string,string|undefined]][]=[] as never;const details:Array<[string,string|undefined]>=[["Start date",f.startDate],["End date",f.endDate],["Start time",f.startTime],["End time",f.endTime],["Prefecture",f.prefecture],["City",f.city],["Venue",f.venue],["Address",f.address],["Price",f.price],["Payment",f.paymentMethods?.join(", ")],["Reservation",f.reservationRequired?"Required":"Not required"],["Rain policy",f.rainPolicy],["Notes",f.notes]];return <main><div className="wrap section"><p className="muted"><Link href="/">Home</Link> / <Link href={`/category/${f.category}`}>{categoryLabel(f.category)}</Link> / {f.nameEn}</p><div className="detail-hero"><img src={f.imageUrl||"https://images.unsplash.com/photo-1528164344705-47542687000d?auto=format&fit=crop&w=1200&q=80"} alt="Festival scene"/><div><div className="eyebrow">{categoryLabel(f.category)}</div><h1>{f.nameEn}</h1><p>{f.nameJa}</p><p className="muted">{f.startDate}{f.endDate?` – ${f.endDate}`:""}<br/>{f.city}, {f.prefecture}</p><div className="tags">{f.activities.map(a=><span className="tag" key={a}>{a}</span>)}</div></div></div><section className="section"><h2>What can you do at this festival?</h2><p className="muted">These activities are designed for visitors who want to join in, not just watch.</p><div className="categories">{f.activities.map(a=><div className="category" key={a}><span>Participate</span><h3>{a}</h3><p className="muted">A welcoming hands-on festival experience.</p></div>)}</div></section><section><h2>Festival information</h2><p>{f.description}</p><div className="info">{details.filter((x):x is [string,string]=>Boolean(x[1])).map(([k,v])=><div key={k}><strong>{k}</strong>{v}</div>)}</div><div className="tags" style={{marginTop:20}}>{f.officialWebsite&&<a className="button" href={f.officialWebsite} target="_blank">Official Website</a>}{(f.reservationUrl||f.ticketUrl)&&<a className="button alt" href={f.reservationUrl||f.ticketUrl} target="_blank">Reservation / Tickets</a>}{f.latitude&&<a className="button alt" href={`https://maps.google.com/?q=${f.latitude},${f.longitude}`} target="_blank">View on Map</a>}</div></section></div></main>}
